#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node *next;
};

/* 头插：返回插入后的新表头；申请失败时返回原表头 */
struct Node *insert_head(struct Node *head, int x)
{
    struct Node *p = (struct Node *)malloc(sizeof(struct Node));
    if (p == NULL) {
        return head;              /* 申请失败，链表不变 */
    }
    p->data = x;
    p->next = head;               /* 先连：新结点指向原首结点 */
    head = p;                     /* 后改头：head 指向新结点 */
    return head;                  /* 把新表头交还给调用者 */
}

void print_list(struct Node *head)
{
    struct Node *cur = head;
    while (cur != NULL) {
        printf("%d -> ", cur->data);
        cur = cur->next;
    }
    printf("NULL\n");
}

int main(void)
{
    struct Node *head = NULL;     /* 空表 */

    head = insert_head(head, 1);  /* 必须接住返回值 */
    head = insert_head(head, 2);
    head = insert_head(head, 3);

    print_list(head);             /* 输出：3 -> 2 -> 1 -> NULL */
    return 0;
}

